<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, nextTick, ref, toRaw } from 'vue';
import { operatorApiService } from 'src/services';
import SubHeader from 'src/pages/Settings/Components/Sub-Header.vue';
import { dynamicObj } from './assets';
import cache from 'src/utils/cache';
import docOperatorIcon from 'src/pages/Invoice/components/doc_operator_icon.vue';
import { ApiExceptions } from 'src/exceptions';
import { encodeData, decodeData } from 'src/utils/cryptoStorage';
interface ChatHistoryItem {
  result: Array<{
    extracted_content: string;
    is_done: boolean;
    include_in_memory: boolean;
  }>;
  state?: {
    screenshot?: string;
  };
}

export default defineComponent({
  name: 'DocOperator',
  components: {
    SubHeader,
    docOperatorIcon,
  },
  mixins: [cache],
  mounted() {
    this.init();
    operatorApiService.connect();
    logInfo('Connected to WebSocket.', this.chatHistory);
  },
  unmounted() {
    logInfo('Component is unmounting. Disconnecting WebSocket.');
    operatorApiService.disconnect();
  },
  watch: {
    chatHistory: {
      deep: true,
      handler: function (newVal, oldVal) {
        if (newVal != oldVal) {
          this.setDataToLocalStorage('chatHistory', this.chatHistory);
        }
      },
    },
    userPrompt: {
      deep: true,
      handler: function (newVal, oldVal) {
        if (newVal != oldVal) {
          this.setDataToLocalStorage('userPrompt', this.userPrompt);
        }
      },
    },
    status: {
      handler: async function (newVal, oldVal) {
        if (
          oldVal == 'completed' &&
          oldVal != newVal &&
          this.downloadedFiles.length > 0
        ) {
          await this.downloadFiles(this.downloadedFiles);
          this.downloadedFiles = [];
        }
      },
    },
  },
  methods: {
    async init() {
      this.userPrompt = this.getDataByKey('userPrompt') || {
        result: [
          {
            extracted_content: '',
            is_done: false,
            include_in_memory: false,
          },
        ],
        used_tool: '',
      };
      this.chatHistory =
        (this.getDataByKey('chatHistory') as ChatHistoryItem[]) || [];
      this.variablePairs = (this.getDataByKey('userVariablePairs') as any) || [
        { key: '', value: '', is_sensitive: false },
      ];
      this.viewUrl = (this.getDataByKey('viewUrl') as string) || '';
      this.apiToken = await operatorApiService.get_token();
      this.docNetTools = await operatorApiService.getDocNetTools();

      operatorApiService.onMessage((data: any) => {
        if (!data) return;

        this.messageId = data.task_id || '';
        this.viewUrl = data.view_url || '';
        this.setDataToLocalStorage('viewUrl', this.viewUrl);

        if (data.downloaded_files) {
          this.downloadedFiles = data.downloaded_files;
        }

        if (data.status === 'completed' && data.model_output) {
          this.chatHistory.push({
            result: data.model_output,
            state: data.state || {},
          });
          this.viewUrl = data.view_url || '';
          this.setDataToLocalStorage('viewUrl', this.viewUrl);
          return;
        }

        if (data.history?.history?.length > 0) {
          this.chatHistory = data.history.history;
        }
      });
    },

    clearChatHistory() {
      this.chatHistory = [];
      this.userPrompt = {
        result: [
          {
            extracted_content: '',
            is_done: false,
            include_in_memory: false,
          },
        ],
        used_tool: '',
      };
      this.hasSentPrompt = false;
      this.runSavedPrompt = false;
      this.deleteVariablePairs();
      this.viewUrl = '';
      this.setDataToLocalStorage('viewUrl', this.viewUrl);
      this.showIFrameOverlay = true;
      this.showBrowser = false;
    },

    getImageSrc(screenshot: string | undefined) {
      if (!screenshot) return '';
      return screenshot.startsWith('data:image')
        ? screenshot
        : 'data:image/png;base64,' + screenshot;
    },

    toggleImage(index: number) {
      if (this.visibleImages[index] === undefined) {
        this.visibleImages[index] = true;
        return;
      }
      this.visibleImages[index] = !this.visibleImages[index];
    },

    async sendMessage(message: any) {
      if (!message) return;
      this.isSending = true;
      this.showIFrameOverlay = true;
      try {
        this.createVariablesDict();
        await operatorApiService.submitChatMessage(
          message,
          '',
          this.apiToken,
          'user_message',
          toRaw(this.variablePairsDict),
          this.activeTool,
        );
        this.userPrompt = {
          result: [
            {
              extracted_content: '💬 ' + message,
              is_done: false,
              include_in_memory: false,
            },
          ],
          used_tool: this.activeTool,
        };
        this.setDataToLocalStorage('userPrompt', this.userPrompt);
        this.message = '';
        this.hasSentPrompt = true;
        this.chatHistory = [];
        this.activeTool = '';
      } catch (error) {
        logError('Error sending message:', error);
        notify.error(this.$t('send_message_failed'));
      } finally {
        this.isSending = false;
      }
    },

    getResponseDescription(entry: any) {
      if (entry[0] && entry[0].is_done && this.userPrompt.used_tool) {
        return (
          (entry[0].extracted_content as string) +
          ' ' +
          this.$t('request_to_docnet')
        );
      } else if (entry[0] && entry[0].extracted_content) {
        return entry[0].extracted_content as string;
      } else if (typeof entry === 'string') {
        return entry;
      } else {
        return 'Waiting for application...';
      }
    },

    openFullScreen(imgSrc: string) {
      this.fullScreenImage = imgSrc;
      this.showFullScreen = true;
    },

    async taskAction(action: string) {
      try {
        this.loading = true;
        await operatorApiService.submitChatMessage(
          this.message,
          this.messageId,
          this.apiToken,
          action,
          {},
          '',
        );
        if (action === 'stop') {
          this.clearChatHistory();
        }
      } catch (error) {
        logError('Error performing task action:', error);
        notify.error(this.$t('task_action_failed'));
      } finally {
        this.loading = false;
      }
    },

    getDisabled() {
      if (this.status === 'running') {
        return false;
      }
      if (this.status !== 'ready' || !this.message) {
        return true;
      }
    },

    isChatEmpty() {
      if (
        this.chatHistory.length > 0 ||
        this.userPrompt.result[0].extracted_content.length > 0
      ) {
        return false;
      }
      return true;
    },

    showVariableConnectorScreen() {
      if (this.showVariableConnector) {
        this.showVariableConnector = false;
        return;
      }
      this.showVariableConnector = true;
    },

    addVariablePair() {
      this.variablePairs.push({ key: '', value: '', is_sensitive: false });
    },

    removeVariablePair(index: number) {
      this.variablePairs.splice(index, 1);
    },

    saveVariablePairs() {
      this.setDataToLocalStorage('userVariablePairs', this.variablePairs);
      this.showVariableConnector = false;
      if (this.runSavedPrompt) {
        this.sendMessage(this.message);
        return;
      }
      notify.success(this.$t('operation_sucessfull'));
    },

    deleteVariablePairs() {
      this.variablePairs = [{ key: '', value: '', is_sensitive: false }];
      this.sensitiveVariables = [];
      this.setDataToLocalStorage('userVariablePairs', this.variablePairs);
    },

    createVariablesDict() {
      this.variablePairsDict = {};
      this.sensitiveVariables = [];
      this.variablePairs.forEach((pair: any) => {
        this.variablePairsDict[pair.key] = pair.value;
        if (pair.is_sensitive) {
          this.sensitiveVariables.push(pair.key);
        }
      });
    },

    createVariablePairs(variableDict: dynamicObj, is_public: boolean) {
      let newVariablePairs = [] as dynamicObj;

      Object.keys(variableDict).forEach((key) => {
        let sensitive = false;
        if (this.sensitiveVariables) {
          if (this.sensitiveVariables.includes(key)) {
            sensitive = true;
          }
        }
        let variable_value = variableDict[key];
        if (is_public) {
          variable_value = '';
        }

        newVariablePairs.push({
          key: key,
          value: variable_value,
          is_sensitive: sensitive,
        });
      });
      this.variablePairs = newVariablePairs;
    },

    showSavePromptScreen() {
      if (this.showSavePrompt) {
        this.showSavePrompt = false;
        if (this.isEditPrompt) {
          this.isEditPrompt = false;
          this.sensitiveVariables = [];
          this.variablePairs = [{ key: '', value: '', is_sensitive: false }];
        }
        return;
      }
      this.showSavePrompt = true;
    },

    async savePrompt() {
      try {
        this.loading = true;

        let userMessage = this.userPrompt.result[0].extracted_content.slice(3);
        if (this.isEditPrompt) {
          userMessage = this.promptText;
        }

        this.createVariablesDict();

        let sensitive_variables = [];
        if (this.sensitiveVariables) {
          sensitive_variables = this.sensitiveVariables;
        }

        for (const [key, value] of Object.entries(this.variablePairsDict)) {
          if (Object.hasOwnProperty.call(this.variablePairsDict, key)) {
            if (value) {
              this.variablePairsDict[key] = await encodeData(value);
            } else {
              this.variablePairsDict[key] = '';
            }
          }
        }

        const dataJson = {
          prompt_id: this.currentPromptId,
          prompt_name: this.promptName,
          prompt_text: userMessage,
          prompt_variables: this.variablePairsDict,
          is_public: this.savePublicly,
          sensitive_variables: sensitive_variables,
          use_tool: this.activeTool,
        };

        const response = await operatorApiService.savePrompt(dataJson);
        await this.loadPrompts();

        notify.success(this.$t('operation_sucessfull'));
        this.showSavePrompt = false;
        this.promptName = '';
        this.savePublicly = false;
        this.currentPromptId = '';
        this.sensitiveVariables = [];
        this.activeTool = '';
      } catch (error) {
        logError('Error saving prompt:', error);
        const msg = ApiExceptions.getErrorMessage(error as dynamicObj);
        notify.error(msg);
      } finally {
        this.loading = false;
      }
    },

    async toggleSidebar() {
      this.sidebarVisible = !this.sidebarVisible;
      if (
        this.sidebarVisible &&
        (!this.orgPromptChats.length || !this.publicPromptChats.length)
      ) {
        await this.loadPrompts();
      }
    },

    async loadPrompts() {
      try {
        this.loading = true;
        const response = await operatorApiService.getAllPrompts(true);
        if (response.success) {
          this.orgPromptChats = response.org_prompts;
          this.publicPromptChats = response.public_prompts;
          this.filteredOrgPrompts = this.orgPromptChats;
          this.filteredPublicPrompts = this.publicPromptChats;
        }
        this.loading = false;
      } catch (error) {
        logError('Error loading prompts:', error);
        const msg = ApiExceptions.getErrorMessage(error as dynamicObj);
        notify.error(msg);
      } finally {
        this.loading = false;
      }
    },

    filterPrompts() {
      nextTick(() => {
        this.filteredOrgPrompts = this.orgPromptChats.filter(
          (e: any) =>
            e.prompt_name
              .toLowerCase()
              .includes(this.searchQuery.toLowerCase()) as string,
        );
        this.filteredPublicPrompts = this.publicPromptChats.filter(
          (e: any) =>
            e.prompt_name
              .toLowerCase()
              .includes(this.searchQuery.toLowerCase()) as string,
        );
      });
    },

    async runPrompt(entry: any, is_public: boolean) {
      this.message = entry.prompt_text;
      if (entry.prompt_variables && entry.prompt_variables != '{"": ""}') {
        this.runSavedPrompt = true;
        this.sensitiveVariables = JSON.parse(entry.sensitive_variables);
        this.createVariablePairs(JSON.parse(entry.prompt_variables), is_public);
      }
      if (
        is_public &&
        entry.prompt_variables &&
        entry.prompt_variables != '{}'
      ) {
        this.showVariableConnectorScreen();
        return;
      }
      this.activeTool = entry.use_tool;
      await this.sendMessage(this.message);
    },

    async editPrompt(entry: any) {
      this.promptName = entry.prompt_name;
      this.savePublicly = entry.is_public;
      this.currentPromptId = entry.id;
      this.promptText = entry.prompt_text;
      this.isEditPrompt = true;
      this.sensitiveVariables = JSON.parse(entry.sensitive_variables);
      let variables = JSON.parse(entry.prompt_variables);
      for (const [key, value] of Object.entries(variables)) {
        if (Object.hasOwnProperty.call(variables, key)) {
          variables[key] = await decodeData(value as any);
        }
      }
      this.createVariablePairs(variables, false);
      this.showSavePromptScreen();
    },

    async deletePrompt(entry: any) {
      try {
        this.loading = true;
        const response = await operatorApiService.deletePrompt(entry);
        if (!response.success) {
          notify.error(this.$t('UNKNOWN_ERROR'));
          return;
        }
        await this.loadPrompts();
        notify.success(this.$t('DELETED_SUCCESSFULLY'));
        this.loading = false;
      } catch (error) {
        logError('Error deleting prompt:', error);
        const msg = ApiExceptions.getErrorMessage(error as dynamicObj);
        notify.error(msg);
      } finally {
        this.loading = false;
      }
    },

    clearValue(index: number) {
      if (this.variablePairs[index]) {
        this.variablePairs[index].value = '';
      }
    },

    async takeBrowserControl() {
      this.showIFrameOverlay = false;
      await this.taskAction('pause');
    },

    async downloadFiles(filenames: string[]) {
      try {
        for (const filename of filenames) {
          const fileBlob = await operatorApiService.downloadOperatorFile(
            filename,
            this.messageId,
          );
          if (!fileBlob) {
            throw new Error(`Failed to download file: ${filename}`);
          }

          const fileURL = window.URL.createObjectURL(new Blob([fileBlob]));
          const fileLink = document.createElement('a');
          fileLink.href = fileURL;
          fileLink.setAttribute('download', filename);
          document.body.appendChild(fileLink);
          fileLink.click();
          document.body.removeChild(fileLink);

          window.URL.revokeObjectURL(fileURL);
        }
      } catch (err) {
        logError('Error during file download:', err);
      }
    },

    handleKeyup(e: any) {
      if (this.message && this.message[this.message.length - 1] === '@') {
        this.showDocNetTools = true;
      }
    },

    useTool(tool: any) {
      this.showDocNetTools = false;
      this.activeTool = tool.name;
      this.message = this.message.slice(0, -1);
    },
  },
  setup() {
    return {
      message: ref(''),
      isSending: ref(false),
      status: ref(operatorApiService.status),
      hasSentPrompt: ref(false),
      chatHistory: ref(
        [] as Array<{
          result?: Array<{
            extracted_content?: string;
            is_done?: boolean;
            success?: boolean;
          }>;
          state?: {
            screenshot?: string;
          };
        }>,
      ),
      userPrompt: ref({
        result: [
          {
            extracted_content: '',
            is_done: false,
            include_in_memory: false,
          },
        ],
        used_tool: '',
      } as any),
      visibleImages: ref({} as dynamicObj),
      showFullScreen: ref(false),
      fullScreenImage: ref(''),
      messageId: ref(''),
      apiToken: ref(''),
      showVariableConnector: ref(false),
      variablePairs: ref([
        { key: '', value: '', is_sensitive: false },
      ] as dynamicObj),
      variablePairsDict: ref({} as dynamicObj),
      showSavePrompt: ref(false),
      promptName: ref(''),
      promptText: ref(''),
      savePublicly: ref(false),
      loading: ref(false),
      sidebarVisible: ref(false),
      orgPromptChats: ref([] as any),
      publicPromptChats: ref([] as any),
      searchQuery: ref(''),
      filteredOrgPrompts: ref([] as any),
      filteredPublicPrompts: ref([] as any),
      currentPromptId: ref(''),
      runSavedPrompt: ref(false),
      isEditPrompt: ref(false),
      sensitiveVariables: ref([] as any),
      viewUrl: ref(''),
      showBrowser: ref(false),
      showIFrameOverlay: ref(true),
      downloadedFiles: ref([] as any),
      docNetTools: ref({ available_tools: [] as any[] }),
      showDocNetTools: ref(false),
      activeTool: ref(''),
    };
  },
});
</script>

